// Oeste Skeleton — Topanga theme (v0.4.7).
// Copy-paste ready. Requires: React 18+, Tailwind with dark: variant, JSX transform.
// Requires Topanga tokens: import src/tokens.css once (or copy src/tokens.json).
// Source: https://github.com/eric2busy/Oeste/blob/main/src/index.js
// Docs: https://oeste.hiddeninwest.com/#/components/skeleton

export function Skeleton({ width = "100%", height = "16px", label }) {
  return (
    <div role="status" aria-label={label} aria-busy="true"
      className="rounded-md bg-[#1c1917]/10 dark:bg-[#f5f3ef]/10"
      style={{ width, height }} />
  );
}
